Q: Spring Security JAAS authentication authorization issue A: <p>Based on: <a href="http://jpam.sourceforge.net/xref/net/sf/jpam/jaas/JpamLoginModule.html" rel="nofollow noreferrer">http://jpam.sourceforge.net/xref/net/sf/jpam/jaas/JpamLoginModule.html</a> and <a href="https://github.com/spring-projects/spring-security/blob/master/core/src/main/java/org/springframework/security/authentication/jaas/AbstractJaasAuthenticationProvider.java" rel="nofollow noreferrer">https://github.com/spring-projects/spring-security/blob/master/core/src/main/java/org/springframework/security/authentication/jaas/AbstractJaasAuthenticationProvider.java</a></p>
<p>Looks like you need to extend JpamLoginModule to change commit's behaviour. There needs to be principals assigned into the subject in your extended JpamLoginModule. Then AbstractJaasAuthenticationProvider (DefaultJaasAuthenticationProvider) will loop through these principals and send them to your authorityGranters (RoleGranter).</p>
<pre class="lang-xml prettyprint-override"><code>&lt;authentication-manager&gt;
    &lt;authentication-provider ref=&quot;jaasAuthProvider&quot; /&gt;
&lt;/authentication-manager&gt;

&lt;beans:bean id=&quot;userService&quot; class=&quot;blah.UserDetailsServiceImpl&quot; /&gt;  

&lt;beans:bean id=&quot;jaasAuthProvider&quot;  class=&quot;org.springframework.security.authentication.jaas.DefaultJaasAuthenticationProvider&quot;&gt;
    &lt;beans:property name=&quot;configuration&quot;&gt;
        &lt;beans:bean class=&quot;org.springframework.security.authentication.jaas.memory.InMemoryConfiguration&quot;&gt;
            &lt;beans:constructor-arg&gt;
                &lt;beans:map&gt;
                    &lt;beans:entry key=&quot;SPRINGSECURITY&quot;&gt;
                        &lt;beans:array&gt;
                            &lt;beans:bean class=&quot;javax.security.auth.login.AppConfigurationEntry&quot;&gt;
                                &lt;beans:constructor-arg value=&quot;blah.RoleGrantingJpamLoginModule&quot; /&gt;
                                &lt;beans:constructor-arg&gt;
                                    &lt;util:constant  static-field=&quot;javax.security.auth.login.AppConfigurationEntry$LoginModuleControlFlag.REQUIRED&quot; /&gt;
                                &lt;/beans:constructor-arg&gt;
                                &lt;beans:constructor-arg&gt;
                                    &lt;beans:map&gt;&lt;/beans:map&gt;
                                &lt;/beans:constructor-arg&gt;
                            &lt;/beans:bean&gt;
                        &lt;/beans:array&gt;
                    &lt;/beans:entry&gt;
                &lt;/beans:map&gt;
            &lt;/beans:constructor-arg&gt;
        &lt;/beans:bean&gt;
    &lt;/beans:property&gt;
    &lt;beans:property name=&quot;authorityGranters&quot;&gt;
        &lt;beans:list&gt;
            &lt;beans:bean class=&quot;blah.RoleGranter&quot; /&gt;
        &lt;/beans:list&gt;
    &lt;/beans:property&gt;
&lt;/beans:bean&gt;
</code></pre>
<pre class="lang-java prettyprint-override"><code>package blah;

import javax.security.auth.Subject;
import javax.security.auth.login.LoginException;

import net.sf.jpam.jaas.JpamLoginModule;

import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;

public class RoleGrantingJpamLoginModule extends JpamLoginModule {
    private Subject subject;

    @Override
    public void initialize(javax.security.auth.Subject subject, javax.security.auth.callback.CallbackHandler callbackHandler, java.util.Map sharedState, java.util.Map options) {
        super.initialize(subject, callbackHandler, sharedState, options);
        this.subject = subject;
    }

    @Override
    public boolean commit() throws LoginException {
        UsernamePasswordAuthenticationToken token = new UsernamePasswordAuthenticationToken(null, null);
        subject.getPrincipals().add(token);
        return super.commit();
    }
}
</code></pre>
<pre class="lang-java prettyprint-override"><code>package blah;

import static java.util.Arrays.asList;

import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.core.userdetails.UsernameNotFoundException;

public class UserDetailsServiceImpl implements UserDetailsService {

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        return new User(username, &quot;password&quot;, asList(new SimpleGrantedAuthority(&quot;ROLE_ADMIN&quot;)));
    }

}
</code></pre>
